def longest_streak(nums):
    if not nums:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(nums) - 1):
        if nums[i] >= nums[i - 1]:
            cur += 1
        if cur > best:
            best = cur
    return best

n = int(input())
nums = list(map(int, input().split()))
print(longest_streak(nums))
